//! Static description of the pf_passive data dictionary, used to build and resolve paths.
//!
//! **WARNING** This file is autogenerated by `imas_updater/build_ids.py`.
//! Any changes will be overwritten.
//!
//! Each leaf carries the function that reads it out of the IDS, so the path a
//! reader follows is written once and checked by the compiler. The `read` closures
//! capture nothing, so they coerce to plain `fn` pointers and the whole description
//! stays a `static`.

#![allow(clippy::all)]

use super::{IndexSpec, Leaf, Node, NodeKind, gather, no_levels};
use crate::dd_base_types::{FLT_0D, FLT_1D, INT_0D, INT_1D, STR_0D};
use crate::ids::pf_passive::PfPassive;
use std::any::Any;

// ============================================================================
// Array-of-structures lengths
// ============================================================================

/// Length of each array-of-structures level along `code_library`.
fn lengths_code_library(pf_passive: &PfPassive, level: usize, _at: &[usize]) -> Option<usize> {
    match level {
        0 => return Some(pf_passive.code.library.len()),
        _ => return None,
    }
}

/// Length of each array-of-structures level along `loop`.
fn lengths_loop(pf_passive: &PfPassive, level: usize, _at: &[usize]) -> Option<usize> {
    match level {
        0 => return Some(pf_passive.r#loop.len()),
        _ => return None,
    }
}

/// Length of each array-of-structures level along `loop_element`.
fn lengths_loop_element(pf_passive: &PfPassive, level: usize, at: &[usize]) -> Option<usize> {
    match level {
        0 => return Some(pf_passive.r#loop.len()),
        1 => return Some(pf_passive.r#loop.get(at[0])?.element.len()),
        _ => return None,
    }
}

